import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.D3oaa6bG.js";const m=JSON.parse('{"title":"Payments","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/payment-methods.md","filePath":"guide/usage/payment-methods.md","lastUpdated":null}'),i={name:"guide/usage/payment-methods.md"};function o(r,e,p,l,d,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h1><h2 id="payment-gateways" tabindex="-1">Payment gateways <a class="header-anchor" href="#payment-gateways" aria-label="Permalink to &quot;Payment gateways&quot;">​</a></h2><p><code>Payment gateways</code> are of technical nature and won&#39;t be visible to the user. You can use the payment gateway settings page to configure your API keys and other settings for each gateway.</p><p>Each gateway can be used by one or many payment methods.</p><p>You can add custom gateways by implementing and registering a <a href="/wn-mall-plugin/development/core/payment-providers.html">Payment provider class</a>.</p><h2 id="payment-methods" tabindex="-1">Payment methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;Payment methods&quot;">​</a></h2><p><code>Payment methods</code> are presented to a customer during checkout. They abstract away the technical nature of a <code>Payment gateway</code>. You can define a name, a description and a logo for each payment method.</p><p>You can also specify special payment instructions (see below) or fees that will be added to the user&#39;s cart during checkout.</p><p>Payment methods use a single <code>Payment gateway</code> to process a payment.</p><h3 id="fees" tabindex="-1">Fees <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;Fees&quot;">​</a></h3><p>You can define fixed and variable fees that will be added to the user&#39;s cart during checkout.</p><p>If, for example, you want to forward your Stripe fees to the customer, you can add <code>0.30 USD</code> as fixed fee and <code>2.9 %</code> as percentage fee.</p><h3 id="payment-instructions" tabindex="-1">Payment instructions <a class="header-anchor" href="#payment-instructions" aria-label="Permalink to &quot;Payment instructions&quot;">​</a></h3><p>You can specify special payment instructions using Twig syntax in the <code>Instructions</code> field of any payment method.</p><p>By default, these instructions will be displayed when using the <a href="./../components/payment-method-selector.html">Payment method selector</a> or <a href="./../components/orders-list.html">Orders list</a> components.</p><p>You can access a <code>order</code> variable (if available) to display additional information. During the checkout process you have access to the <code>cart</code> model since no order was created yet.</p><p>Sample instructions for a &quot;Payment in advance&quot; method could be:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">{# </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    Check if the order has been created yet.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    During checkout this might not be the case</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Send your payment to:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    *Bank information*</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Payment id: {{ order.payment_hash }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><h2 id="pdf-invoices" tabindex="-1">PDF invoices <a class="header-anchor" href="#pdf-invoices" aria-label="Permalink to &quot;PDF invoices&quot;">​</a></h2><p>If you wish to send a PDF invoice to your customers during checkout you can do so starting from version 1.8.0.</p><p>When updating a payment method via the backend, you can select a PDF partial from the select box.</p><p>PDF partials need to be placed in your theme&#39;s partial folder at <code>partials/mallPDF/&lt;custom-name&gt;/default.htm</code>.</p><p>As soon as you have created this partial, it will be selectable in the payment method form.</p><div><p>Your invoice has to be a complete HTML document. You have access to all order data using the <code>{{ order }}</code> variable.</p></div><p>Take a look at the demo theme for an example implementation: <a href="https://github.com/wintercms/wn-mall-theme/tree/master/partials/mallPDF/order" target="_blank" rel="noreferrer">https://github.com/wintercms/wn-mall-theme/tree/master/partials/mallPDF/order</a></p><p>Read more about the PDF support <a href="/wn-mall-plugin/development/core/pdf.html">on the PDF page</a>.</p>`,26)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
